import * as T from 'three';
import {createRanchComposer} from '/simulations/ranch-composer.js';
import {applyVariant,VARIANTS} from '/simulations/variants/new-england.mjs';
import {dressingAsset,enclosureAsset} from '/simulations/variants/dressing.mjs';
import {applyDorfRanch} from '/simulations/dorf-ranch-materials.mjs';
import {OrbitControls} from '/simulations/vendor/OrbitControls.js';
import {sandboxWheel} from '/simulations/vendor/sandbox-camera.mjs';
const $=s=>document.querySelector(s),host=$('#view'),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1;host.prepend(renderer.domElement);
const camera=new T.PerspectiveCamera(34,1,.005,1200),orbit=new OrbitControls(camera,renderer.domElement);orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};orbit.minDistance=1.2;orbit.maxDistance=800;orbit.maxPolarAngle=Math.PI*.47;orbit.enableDamping=false;
renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});
const scenes=[0,1].map(()=>{const scene=new T.Scene();scene.background=new T.Color('#e5e4d7');scene.add(new T.HemisphereLight('#fff3dc','#737d66',2));const sun=new T.DirectionalLight('#ffebd2',3);sun.position.set(-12,18,10);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-12,right:12,top:12,bottom:-12,near:.1,far:80});sun.shadow.normalBias=.005;scene.add(sun);return scene;});
const composer=await createRanchComposer({variants:false}),manifest=await(await fetch('/simulations/variants/provenance.json')).json();let models=[],token=0,box;
for(const [id,spec]of Object.entries(VARIANTS)){const o=document.createElement('option');o.value=id;o.textContent=spec.name;$('#asset').append(o);}for(let i=1;i<=8;i++){const o=document.createElement('option');o.value=i;o.textContent='Seed '+i;$('#seed').append(o);}
function dispose(o){o?.traverse(n=>{if(n.geometry&&!n.userData.sharedGeometry)n.geometry.dispose();for(const m of Array.isArray(n.material)?n.material:[n.material])if(m&&!m.userData.shared)m.dispose();});}
async function model(id,stage,seed){if(['grass','rock','enclosure'].includes(id)){const g=id==='enclosure'?enclosureAsset():dressingAsset(id);return applyVariant(g,id,{seed,stage});} // Use the same calibrated source and recipe as the ranch.
 return composer.model(id,{stage,seed});}
async function load(){const request=++token,id=$('#asset').value,stage=$('#variant-stage').value,seed=Number($('#seed').value);$('#error').textContent='Loading source assets…';try{const next=await Promise.all(['original',stage].map(s=>model(id,s,seed)));if(request!==token){next.forEach(dispose);return;}models.forEach((m,i)=>{scenes[i].remove(m);dispose(m);});models=next;const displayScale=id==='grass'||id==='rock'?20:1;models.forEach(m=>m.scale.multiplyScalar(displayScale));models.forEach((m,i)=>{applyDorfRanch(m);scenes[i].add(m);});box=new T.Box3();models.forEach(m=>box.union(new T.Box3().setFromObject(m)));fit();$('.after').textContent=stage==='full'?'Materials + geometry':'Materials only';$('#name').textContent=VARIANTS[id].name;$('#changes').replaceChildren(...VARIANTS[id].changes.slice(0,stage==='materials'?1:undefined).map(t=>{const li=document.createElement('li');li.textContent=t;return li;}));const source=manifest.assets.find(a=>a.sourceId===id);$('#provenance').textContent=JSON.stringify({...source,recipe:'new-england-v1',seed,stage,displayMagnification:displayScale},null,2);$('#source').href=source.sourceUrl;$('#error').textContent='';}catch(e){$('#error').textContent=e.message;console.error(e);}}
function fit(){if(!box)return;const c=box.getCenter(new T.Vector3()),size=box.getSize(new T.Vector3()),distance=Math.max(size.x/camera.aspect,size.y,size.z)*.75/Math.tan(T.MathUtils.degToRad(17));orbit.target.copy(c);camera.position.copy(c).add(new T.Vector3(.8,.65,1).normalize().multiplyScalar(distance));orbit.update();}
function resize(){const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=innerWidth<=650?w/(h/2):(w/2)/h;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(host);resize();for(const id of ['asset','variant-stage','seed'])$('#'+id).onchange=load;$('#fit').onclick=fit;$('#help').onclick=()=>$('dialog').showModal();await load();
function frame(){if(!document.hidden){const w=host.clientWidth,h=host.clientHeight,stack=innerWidth<=650;renderer.setScissorTest(true);scenes.forEach((s,i)=>{const x=stack?0:i*w/2,y=stack?(1-i)*h/2:0,vw=stack?w:w/2,vh=stack?h/2:h;renderer.setViewport(x,y,vw,vh);renderer.setScissor(x,y,vw,vh);renderer.render(s,camera);});renderer.setScissorTest(false);}requestAnimationFrame(frame);}frame();
const move=()=>{const b=$('#app-settings-toggle');if(!b)return false;$('header').append(b);return true;};if(!move()){const observer=new MutationObserver(()=>{if(move())observer.disconnect();});observer.observe(document.body,{childList:true});}

const sharing=document.querySelector('#ranch-view-sharing');if(sharing)document.querySelector('dialog').prepend(sharing);
